-- PT113-S4-Q4. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT113-S4-Q4$batch12$ AND q.stimulus=$batch12$An overwhelming number of industry’s chief executive officers who earn over $250,000 annually attended prestigious business schools. Therefore Greta Harris, who attended a prestigious business school, must be a chief executive officer who earns over $250,000 annually.$batch12$ AND q.prompt=$batch12$Which one of the following exhibits flawed reasoning most nearly parallel to that exhibited in the argument above?$batch12$ AND q.correct_choice=$batch12$E$batch12$) THEN RAISE EXCEPTION 'Question changed: PT113-S4-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT113-S4-Q4$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S4-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT113-S4-Q4$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Greta Harris must be a high-earning CEO.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Most high-earning CEOs attended prestigious business schools. Greta attended one.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Most A are B. X is B. So X is A. Most high earners went to these schools, but most graduates may not be high earners. The argument reverses the relationship.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Most A are B; X is B; so X is A.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT113-S4-Q4$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Fred is already known to be high-strung. The leap is to future health problems.$batch12$), ($batch12$B$batch12$, $batch12$This compares two singers' future fame.$batch12$), ($batch12$C$batch12$, $batch12$This concludes something about Italians in general.$batch12$), ($batch12$D$batch12$, $batch12$This draws a causal conclusion about luck.$batch12$), ($batch12$E$batch12$, $batch12$Most successful singers studied several languages. Eileen did, so the argument concludes Eileen is a successful singer. Same reversal.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT113-S4-Q4$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
